// DMA_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module DMA_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [31:0] c_src0,
  input logic [31:0] c_dst0,
  input logic [15:0] c_len0,
  input logic [31:0] c_fill0,
  input logic [31:0] c_src1,
  input logic [31:0] c_dst1,
  input logic [15:0] c_len1,
  input logic [31:0] c_fill1,
  input logic [31:0] c_src2,
  input logic [31:0] c_dst2,
  input logic [15:0] c_len2,
  input logic [31:0] c_fill2,
  input logic [31:0] c_src3,
  input logic [31:0] c_dst3,
  input logic [15:0] c_len3,
  input logic [31:0] c_fill3,
  input logic  c_mode0,
  input logic  c_mode1,
  input logic  c_mode2,
  input logic  c_mode3,
  input logic  c_start0,
  input logic  c_start1,
  input logic  c_start2,
  input logic  c_start3,
  input logic [3:0] c_pending,
  input logic  c_busy,
  input logic [1:0] c_active_ch,
  input logic  c_err,
  input logic [31:0] c_checksum,
  input logic [31:0] c_cycles,
  input logic  c_done0,
  input logic  c_done1,
  input logic  c_done2,
  input logic  c_done3,
  input logic  c_err_irq
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 26;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:25];          // model of every stored word
  logic [4:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;

  always_comb begin
    m_set = '0;
    if (c_done0) m_set[0] = 1'b1;
    if (c_done1) m_set[1] = 1'b1;
    if (c_done2) m_set[2] = 1'b1;
    if (c_done3) m_set[3] = 1'b1;
    if (c_err_irq) m_set[4] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
      m_w[24] <= 32'h0;
      m_w[25] <= 32'h0;
      m_pulse_CMD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 14) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 15) m_w[15] <= ((m_w[15] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 16) m_w[16] <= ((m_w[16] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 17) m_w[17] <= ((m_w[17] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 18) m_w[18] <= ((m_w[18] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 19) m_w[19] <= ((m_w[19] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      if (m_wr && m_map && m_idx == 20) m_w[20] <= ((m_w[20] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 21) m_w[21] <= ((m_w[21] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 22) ? PWDATA & m_be & 32'hF : 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h5C090100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return m_w[14];
      15: return m_w[15];
      16: return m_w[16];
      17: return m_w[17];
      18: return m_w[18];
      19: return m_w[19];
      20: return m_w[20];
      21: return m_w[21];
      22: return 0;
      23: return (32'(c_pending) << 0) | (32'(c_busy) << 4) | (32'(c_active_ch) << 5) | (32'(c_err) << 7);
      24: return (32'(c_checksum) << 0);
      25: return (32'(c_cycles) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][4:0] & m_w[2][4:0]))
  `SVA_INV(a_core_src0, c_src0 == m_w[5][31:0])
  `SVA_INV(a_core_dst0, c_dst0 == m_w[6][31:0])
  `SVA_INV(a_core_len0, c_len0 == m_w[7][15:0])
  `SVA_INV(a_core_fill0, c_fill0 == m_w[8][31:0])
  `SVA_INV(a_core_src1, c_src1 == m_w[9][31:0])
  `SVA_INV(a_core_dst1, c_dst1 == m_w[10][31:0])
  `SVA_INV(a_core_len1, c_len1 == m_w[11][15:0])
  `SVA_INV(a_core_fill1, c_fill1 == m_w[12][31:0])
  `SVA_INV(a_core_src2, c_src2 == m_w[13][31:0])
  `SVA_INV(a_core_dst2, c_dst2 == m_w[14][31:0])
  `SVA_INV(a_core_len2, c_len2 == m_w[15][15:0])
  `SVA_INV(a_core_fill2, c_fill2 == m_w[16][31:0])
  `SVA_INV(a_core_src3, c_src3 == m_w[17][31:0])
  `SVA_INV(a_core_dst3, c_dst3 == m_w[18][31:0])
  `SVA_INV(a_core_len3, c_len3 == m_w[19][15:0])
  `SVA_INV(a_core_fill3, c_fill3 == m_w[20][31:0])
  `SVA_INV(a_core_mode0, c_mode0 == m_w[21][0:0])
  `SVA_INV(a_core_mode1, c_mode1 == m_w[21][1:1])
  `SVA_INV(a_core_mode2, c_mode2 == m_w[21][2:2])
  `SVA_INV(a_core_mode3, c_mode3 == m_w[21][3:3])
  `SVA_INV(a_core_start0, c_start0 == m_pulse_CMD[0])
  `SVA_INV(a_core_start1, c_start1 == m_pulse_CMD[1])
  `SVA_INV(a_core_start2, c_start2 == m_pulse_CMD[2])
  `SVA_INV(a_core_start3, c_start3 == m_pulse_CMD[3])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_src0 == 32'h0 && c_dst0 == 32'h0 && c_len0 == 16'h0 && c_fill0 == 32'h0 && c_src1 == 32'h0 && c_dst1 == 32'h0 && c_len1 == 16'h0 && c_fill1 == 32'h0 && c_src2 == 32'h0 && c_dst2 == 32'h0 && c_len2 == 16'h0 && c_fill2 == 32'h0 && c_src3 == 32'h0 && c_dst3 == 32'h0 && c_len3 == 16'h0 && c_fill3 == 32'h0 && c_mode0 == 1'h0 && c_mode1 == 1'h0 && c_mode2 == 1'h0 && c_mode3 == 1'h0 && c_start0 == 1'h0 && c_start1 == 1'h0 && c_start2 == 1'h0 && c_start3 == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_SRC0, m_rd && m_map && m_idx == 5)
  `FC(wr_SRC0, m_wr && m_map && m_idx == 5)
  `FC(rd_DST0, m_rd && m_map && m_idx == 6)
  `FC(wr_DST0, m_wr && m_map && m_idx == 6)
  `FC(rd_LEN0, m_rd && m_map && m_idx == 7)
  `FC(wr_LEN0, m_wr && m_map && m_idx == 7)
  `FC(rd_FILL0, m_rd && m_map && m_idx == 8)
  `FC(wr_FILL0, m_wr && m_map && m_idx == 8)
  `FC(rd_SRC1, m_rd && m_map && m_idx == 9)
  `FC(wr_SRC1, m_wr && m_map && m_idx == 9)
  `FC(rd_DST1, m_rd && m_map && m_idx == 10)
  `FC(wr_DST1, m_wr && m_map && m_idx == 10)
  `FC(rd_LEN1, m_rd && m_map && m_idx == 11)
  `FC(wr_LEN1, m_wr && m_map && m_idx == 11)
  `FC(rd_FILL1, m_rd && m_map && m_idx == 12)
  `FC(wr_FILL1, m_wr && m_map && m_idx == 12)
  `FC(rd_SRC2, m_rd && m_map && m_idx == 13)
  `FC(wr_SRC2, m_wr && m_map && m_idx == 13)
  `FC(rd_DST2, m_rd && m_map && m_idx == 14)
  `FC(wr_DST2, m_wr && m_map && m_idx == 14)
  `FC(rd_LEN2, m_rd && m_map && m_idx == 15)
  `FC(wr_LEN2, m_wr && m_map && m_idx == 15)
  `FC(rd_FILL2, m_rd && m_map && m_idx == 16)
  `FC(wr_FILL2, m_wr && m_map && m_idx == 16)
  `FC(rd_SRC3, m_rd && m_map && m_idx == 17)
  `FC(wr_SRC3, m_wr && m_map && m_idx == 17)
  `FC(rd_DST3, m_rd && m_map && m_idx == 18)
  `FC(wr_DST3, m_wr && m_map && m_idx == 18)
  `FC(rd_LEN3, m_rd && m_map && m_idx == 19)
  `FC(wr_LEN3, m_wr && m_map && m_idx == 19)
  `FC(rd_FILL3, m_rd && m_map && m_idx == 20)
  `FC(wr_FILL3, m_wr && m_map && m_idx == 20)
  `FC(rd_MODE, m_rd && m_map && m_idx == 21)
  `FC(wr_MODE, m_wr && m_map && m_idx == 21)
  `FC(rd_CMD, m_rd && m_map && m_idx == 22)
  `FC(wr_CMD, m_wr && m_map && m_idx == 22)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 23)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 23)
  `FC(rd_CHECKSUM, m_rd && m_map && m_idx == 24)
  `FC(wr_CHECKSUM, m_wr && m_map && m_idx == 24)
  `FC(rd_CYCLES, m_rd && m_map && m_idx == 25)
  `FC(wr_CYCLES, m_wr && m_map && m_idx == 25)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_DONE0_set, m_set[0])
  `FC(irq_DONE0_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_DONE0_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_DONE0_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_DONE1_set, m_set[1])
  `FC(irq_DONE1_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_DONE1_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_DONE1_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_DONE2_set, m_set[2])
  `FC(irq_DONE2_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_DONE2_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_DONE2_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_DONE3_set, m_set[3])
  `FC(irq_DONE3_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_DONE3_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_DONE3_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_ERR_set, m_set[4])
  `FC(irq_ERR_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_ERR_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_ERR_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(cmd_start0, m_pulse_CMD[0])
  `FC(cmd_start1, m_pulse_CMD[1])
  `FC(cmd_start2, m_pulse_CMD[2])
  `FC(cmd_start3, m_pulse_CMD[3])
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind DMA_apb DMA_apb_sva u_apb_sva (.*);
